head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF05414.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.dts_Recv;
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_143;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //수익증권 변경상장

scwin.fn_initItem = function() {
    $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, LIST_METHD_TP_CD_3);
    $c.stf.setObjectValue(txb_ISU_RSN_CONTN, "수익증권 일부 중도환수");
};
scwin.fn_calTrstOrgnVal = function() {
    try {
        var vsum = eval(parseInt($c.stf.getObjectValue(edt_BFCHG_TRST_ORGN_VAL), 10)) + eval(parseInt($c.stf.getObjectValue(edt_INCDEC_TRST_ORGN_VAL), 10));
        $c.stf.setObjectValue(edt_AFCHG_TRST_ORGN_VAL, vsum);
    } catch (err) {
        $c.win.alert("[증권수 합산처리 중  오류]");
    }
};
scwin.fn_calTotStkCnt = function() {
    try {
        var vsum = eval(parseInt($c.stf.getObjectValue(edt_BFCHG_TOT_STKCNT), 10)) + eval(parseInt($c.stf.getObjectValue(edt_INCDEC_TOT_STKCNT), 10));
        $c.stf.setObjectValue(edt_AFCHG_TOT_STKCNT, vsum);
    } catch (err) {
        $c.win.alert("[증권수 합산처리 중  오류]");
    }
};
scwin.fn_SetHeader = function() {
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BC_CHGLIST_LISTING_INOUT";
    dts_Isu.reset();
    dts_Isu.insertRow();
    //alert(dts_Isu.text+" dts_Isu.text");

};
scwin.fn_recv_read_sync = function(row) {
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.dts_Recv.getCellData(row, "BZ_PROCS_NO"));
    dts_Isu.setCellData(1, "ACPT_NO", scwin.dts_Recv.getCellData(row, "ACPT_NO"));
    scwin.fn_bf_read_sync();
    dts_Isu.setCellData(1, "INCDEC_TRST_ORGN_VAL", scwin.dts_Recv.getCellData(row, "INCDEC_TRST_ORGN_VAL"));
    dts_Isu.setCellData(1, "INCDEC_TOT_STKCNT", scwin.dts_Recv.getCellData(row, "INCDEC_TOT_STKCNT"));
    scwin.fn_calTrstOrgnVal();
    scwin.fn_calTotStkCnt();
    dts_Isu.setCellData(1, "REMK", scwin.dts_Recv.getCellData(scwin.dts_Recv.getFocusedRowIndex(), "REMK"));
    scwin.fn_initItem();
};
scwin.fn_bf_read_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Bf_Isu.DataID = encodeURI(url);
    dts_Bf_Isu.reset();
    dts_Isu.setCellData(1, "BFCHG_TRST_ORGN_VAL", dts_Bf_Isu.getCellData(1, "BFCHG_TRST_ORGN_VAL"));
    dts_Isu.setCellData(1, "BFCHG_TOT_STKCNT", dts_Bf_Isu.getCellData(1, "BFCHG_TOT_STKCNT"));
};
scwin.fn_read_sync = function(row) {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INCDEC_TRST_ORGN_VAL) == "") {
        $c.win.alert("[증감 신탁원본액]을 입력하세요.");
        edt_INCDEC_TRST_ORGN_VAL.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_INCDEC_TRST_ORGN_VAL, '증감 신탁원본액')) return false;

    if ($c.stf.getObjectValue(edt_AFCHG_TRST_ORGN_VAL) == "") {
        $c.win.alert("[변경후 신탁원본액]을 입력하세요.");
        edt_AFCHG_TRST_ORGN_VAL.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_AFCHG_TRST_ORGN_VAL, '변경후 신탁원본액')) return false;


    if ($c.stf.getObjectValue(edt_INCDEC_TOT_STKCNT) == "") {
        $c.win.alert("[증감 좌수]를 입력하세요.");
        edt_INCDEC_TOT_STKCNT.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_INCDEC_TOT_STKCNT, '증감 좌수')) return false;


    if ($c.stf.getObjectValue(edt_AFCHG_TOT_STKCNT) == "") {
        $c.win.alert("[변경후 총좌수]를 입력하세요.");
        edt_AFCHG_TOT_STKCNT.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_AFCHG_TOT_STKCNT, '변경후 총좌수')) return false;

    if ($c.stf.getObjectValue(txb_ISU_RSN_CONTN) == "") {
        $c.win.alert("[변경사유]를 입력하세요.");
        txb_ISU_RSN_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_REMK).length > 500) {
        $c.win.alert("[비고]항목이 입력사이즈를 초과하였씁니다.");
        txa_REMK.focus();
        return false;
    }
    return true;
};
scwin.fn_checkNumber = function(obj, str) {
    /*
    if (getObjectValue(obj) <= 100) {
    	alert("["+str+"]를 '"+getObjectValue(obj)+"'으로 입력하셨습니다. 확인 후 재입력바랍니다.");obj.focus();return false;
    }
    */
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vAcptNo == "") {
            scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            //dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};
scwin.fn_trs = function(trsIdx) {
    if (trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    //alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    //dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;
    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "ISU_CD", $c.stf.getObjectValue(txb_ISU_CD));
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd);
    //alert('[dts_Isu]'+dts_Isu.text);

    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveIsuIssChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",ACPT_NO=" + scwin.vAcptNo + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_CHG_ISS_BC_HIST;
    trs_Save.Post();
};
scwin.fn_RecvtIsuDel = function() {
    if (scwin.vAcptNo == "") {
        $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    scwin.fn_delete();
};
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};



//2010.03.29 변경신탁원본액과, 수익증권총좌수 추가 (INCDEC_TRST_ORGN_VAL, INCDEC_TOT_STKCNT)
scwin.fn_dscl_ctnt = function() {
    var vCtnt = "";
    vCtnt += "◎ " + $c.stf.getObjectValue(txb_ISU_NM) + " 변경상장 내역";
    vCtnt += "\r\n";
    vCtnt += "① 구분(변경전 -> 변경후)";
    vCtnt += "\r\n";
    vCtnt += "    ㉮ 신탁원본액 : " + $c.stf.addComma(dts_Isu.getCellData(1, "BFCHG_TRST_ORGN_VAL")) + "원 -> " + $c.stf.addComma(dts_Isu.getCellData(1, "AFCHG_TRST_ORGN_VAL")) + "원 (" + $c.stf.addCommaMinus(dts_Isu.getCellData(1, "INCDEC_TRST_ORGN_VAL")) + "원)";
    vCtnt += "\r\n";
    vCtnt += "    ㉯ 수익증권총좌수 : " + $c.stf.addComma(dts_Isu.getCellData(1, "BFCHG_TOT_STKCNT")) + "좌 -> " + $c.stf.addComma(dts_Isu.getCellData(1, "AFCHG_TOT_STKCNT")) + "좌 (" + $c.stf.addCommaMinus(dts_Isu.getCellData(1, "INCDEC_TOT_STKCNT")) + "좌)";
    vCtnt += "\r\n";
    vCtnt += "② 1좌당 원본액 : " + $c.stf.addComma(dts_Isu.getCellData(1, "PARVAL")) + "원";
    vCtnt += "\r\n";
    vCtnt += "③ 변경상장일 : " + scwin.dateForm(dts_Isu.getCellData(1, "LIST_DD"));
    vCtnt += "\r\n";
    vCtnt += "④ 변경사유 : " + dts_Isu.getCellData(1, "ISU_RSN_CONTN");
    vCtnt += "\r\n";
    vCtnt += "⑤ 표준코드 : " + dts_Isu.getCellData(1, "ISU_CD") + " (단축코드:" + dts_Isu.getCellData(1, "ISU_SRT_CD") + ")";
    //alert(vCtnt);
    return vCtnt;
};
scwin.fn_dscl = async function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if ($c.cp.isModified(dts_Isu)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68911";
        arr[1] = scwin.vBzProcsNo; //vBzProcsNo ;
        arr[2] = scwin.vIsurCd;
        arr[3] = '1';
        arr[4] = scwin.fn_dscl_ctnt();
        arr[5] = $c.stf.getObjectValue(txb_ISU_NM);
        //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        //CopyDataSet( dts_DsclMst , param_dts_mst) ;
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 750;
    var hgt = 820;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_all_list_sync;
    fr_fn_list_sync();
};
scwin.edt_INCDEC_TOT_STKCNT_OnKillFocus = function() {
    scwin.fn_calTotStkCnt();
};
scwin.edt_INCDEC_TRST_ORGN_VAL_OnKillFocus = function() {
    scwin.fn_calTrstOrgnVal();
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_RecvIsuDel_onclick = function() {
    scwin.fn_RecvtIsuDel();
};
scwin.dts_Bf_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Bf_Isu);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == '')) {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_LIST_DD, false);
        $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
    }
    if (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == "") {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel.gif";
        btn_RecvIsuDel.setDisabled(false);
    } else {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_RecvIsuDel.setDisabled(true);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh(); // 목록 다시 조회

    if (scwin.TR_JOB == 'D') {
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
        buttonSet.setUpdateStatus();
    }
};
scwin.gform_onload = function() {
    //var parentWin = fn_GetProvider();
    var parentWin = $c.frame.path("../");
    //alert('[parentWin]'+parentWin);
    scwin.dts_Recv = parentWin.scwin.dts_Recv;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vAcptNo = parentWin.scwin.vAcptNo;
    scwin.vIsurCd = parentWin.scwin.vIsurCd;
    scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
    $c.stf.setObjectValue(txb_ISU_CD, $c.stf.getObjectValue(parentWin.txb_ISU_CD));
    $c.stf.setObjectValue(txb_ISU_NM, $c.stf.getObjectValue(parentWin.txb_ISU_NM));
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성s
    //buttonSet.setDrftInfo( btn_Drft, fn_drft );			// 기안

    if (scwin.vOpenTyp == "R") {
        scwin.fn_SetHeader();
        scwin.fn_recv_read_sync(scwin.dts_Recv.getFocusedRowIndex());
        buttonSet.setInsertStatus();
    } else if (scwin.vOpenTyp == "H") {
        scwin.fn_read_sync();
    } else if (scwin.vOpenTyp == "N") {
        scwin.fn_SetHeader();
        scwin.fn_bf_read_sync();
        scwin.fn_initItem();
    }
    buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, SECUGRP_ID_BC, scwin.vIsurCd, js_dep_cd);
};
